-- Independent Dadyoom teaching supports, not claims about the contents of official books.
-- Idempotent: update only genuinely empty published lessons; add each origin/type once.
DO $dadyoom$
DECLARE
  r RECORD;
  target_id uuid;
  target_content text;
BEGIN
  FOR r IN SELECT * FROM jsonb_to_recordset('[{"n":1,"skill":"النعت وتبعيته للمنعوت","passage":"في «قرأتُ كتابًا مفيدًا» كلمة «مفيدًا» نعت منصوب مثل منعوته «كتابًا»، وفي «الكتابُ المفيدُ نافعٌ» يتبع النعت المنعوت في التعريف والرفع. ينبغي مراعاة المطابقة في التذكير والتأنيث والعدد مع قواعد جمع غير العاقل.","prompt":"ما إعراب «مفيدًا» في المثال الأول؟","correct":"نعت منصوب","w1":"فاعل مرفوع","w2":"خبر كان","w3":"مبتدأ","practice":"كوّن ست جمل تنوع فيها النعت في الإعراب والتعريف والتذكير، ثم أعرب المنعوت والنعت."},{"n":2,"skill":"التوكيد اللفظي والمعنوي","passage":"«وصلَ وصلَ الفريقُ» مثال على توكيد لفظي بتكرار الفعل، و«حضر الطلابُ كلُّهم» توكيد معنوي بـ«كل» مضافة إلى ضمير يعود على المؤكد. يتبع التوكيد المعنوي المؤكد في الإعراب، ولا يُعد كل تكرار ناتج عن خطأ في التحرير توكيدًا بليغًا.","prompt":"ما نوع التوكيد في «حضر الطلاب كلهم»؟","correct":"توكيد معنوي","w1":"بدل","w2":"نعت","w3":"حال","practice":"اكتب أربعة تراكيب لتوكيد لفظي ومعنوي مع تحديد التابع والمتبوع وضبطهما."},{"n":3,"skill":"الإبدال والإعلال في البنية الصرفية","passage":"الإبدال وضع حرف مكان آخر وفق قاعدة صوتية أو صرفية مثل إبدال تاء الافتعال طاء في «اصطبر»، أما الإعلال فمتصل بأحوال حروف العلة مثل الحذف في «قُل» من «قال». يجب فهم الأصل والوزن وسبب التحول قبل تحديد المصطلح.","prompt":"ما الظاهرة المرتبطة بتبديل تاء الافتعال طاءً؟","correct":"الإبدال","w1":"النداء","w2":"النعت","w3":"العطف","practice":"استخرج من مرجع صرفي مثالين للإبدال ومثالين للإعلال، وبين الصيغة الأصلية والنتيجة."},{"n":4,"skill":"التقاء همزتين في كلمة واحدة","passage":"في صيغ تتجاور فيها همزتان قد يقع تحقيق أو تسهيل أو إبدال بحسب نوع الكلمة والقراءة والقاعدة المعتمدة، ولا يجوز خلط مسائل رسم الهمزة في الإملاء بأحكام الأداء القرآني. في كتابة الفعل «أأنت» تظهر همزتا استفهام وقطع في كلمتين مستقلتين، فلا يصلح دليلًا على التقاء الهمزتين في كلمة واحدة.","prompt":"ما المنهج الصحيح لتصنيف همزتين متجاورتين؟","correct":"التحقق من البنية والرسم والقاعدة","w1":"قياس جميع الحالات على مثال واحد","w2":"حذف إحدى الهمزتين دائمًا","w3":"اعتبارهما حرف جر","practice":"اعرض ثلاثة أمثلة صحيحة من مرجع صرفي موثوق لهمزتين في كلمة واحدة وفسر حكم كل مثال."},{"n":5,"skill":"الإنشاء الطلبي وغير الطلبي","passage":"«أغلقْ البابَ» إنشاء طلبي يفيد الأمر، و«ما أجملَ الصدقَ!» إنشاء غير طلبي يفيد التعجب. الإنشاء لا يوصف بالصدق والكذب لذاته بالطريقة نفسها التي يوصف بها الخبر، وتتحدد أغراضه البلاغية بحسب السياق.","prompt":"أي أسلوب إنشاء غير طلبي في المثالين؟","correct":"ما أجمل الصدق","w1":"أغلق الباب","w2":"المكتبة مفتوحة","w3":"قرأ الطالب","practice":"اكتب ست جمل إنشائية متنوعة، ثم صنفها إلى طلبية وغير طلبية ووضح الغرض."},{"n":6,"skill":"التمني بأداة ليت","passage":"«ليتَ الوقتَ يتسعُ للمراجعة» أسلوب تمني بـ«ليت»، واسمها «الوقتَ» منصوب وخبرها جملة فعلية بحسب التحليل، ويعبر التمني عن رغبة قد يتعذر حصولها أو يبعد. نميزه عن توقع مؤسس على خطة عملية.","prompt":"ما أداة التمني في المثال؟","correct":"ليت","w1":"هل","w2":"إن","w3":"من","practice":"اكتب أربع جمل تمنٍ في سياقات مختلفة، ثم اضبط اسم ليت وبين الفرق عن الترجي."},{"n":7,"skill":"الأمر وصيغ الطلب","passage":"«اكتبْ الملاحظاتِ» فعل أمر مباشر، وقد يفهم الطلب أيضًا من لام الأمر في «لِيكتبْ الطالبُ ملاحظاته». يختلف الأسلوب من حيث العلاقة بين المتكلم والمخاطب والغرض: توجيه أو التماس أو دعاء بحسب المقام.","prompt":"ما صيغة الطلب في «ليكتب الطالب»؟","correct":"لام الأمر مع المضارع المجزوم","w1":"لام التعليل","w2":"لا الناهية","w3":"خبر مؤكد","practice":"اكتب أوامر في سياق تربوي مهذب، ثم حلل الصيغة والإعراب والغرض من كل جملة."},{"n":8,"skill":"عطف النسق ومعاني أو","passage":"«اقرأ قصةً أو مقالًا» قد تفيد «أو» التخيير في سياق اختيار واحد من بديلين، و«اشرب ماءً أو عصيرًا» تعرض بديلين. وقد تفيد الإباحة أو الشك أو التقسيم بحسب السياق، فلا تحصر معناها في التخيير.","prompt":"متى تفيد «أو» التخيير في المثال؟","correct":"عند عرض بديلين لاختيار أحدهما","w1":"عندما تأتي بعد اسم علم فقط","w2":"في كل أسلوب نهي","w3":"بعد كان فقط","practice":"أنشئ ست جمل تستخدم «أو» بمعان مختلفة ثم اشرح القرينة والمعطوف والمعطوف عليه."},{"n":9,"skill":"البدل وتطابق المرجع","passage":"في «قدمَ المهندسُ ساميٌّ المقترحَ» يمكن اعتبار «ساميٌّ» بدلًا مطابقًا من «المهندسُ» إذا كانا الشخص نفسه، مع مراعاة صحة الاسم وضبطه، والأوضح «قدم المهندسُ خالدٌ المقترحَ». يتبع البدل المبدل منه في الإعراب بحسب نوعه.","prompt":"ما إعراب «خالدٌ» في «قدم المهندس خالد المقترح»؟","correct":"بدل مطابق مرفوع","w1":"مفعول به منصوب","w2":"حال","w3":"خبر كان","practice":"اكتب ثلاث جمل لبدل كل من كل، وأخرى لبعض من كل، مع تفسير الرابط والإعراب."},{"n":10,"skill":"إبدال الألف ياء أو واوًا","passage":"يتحدد تحول الألف في التصريف بموضعها وأصلها الواوي أو اليائي عند بناء صيغ مختلفة، مثل إعادة الألف إلى أصلها في تثنية «عصا» فنقول «عصوان»، وفي «فتى» فنقول «فتيان». دراسة الفعل أو الاسم وجذره أدق من قاعدة شكلية واحدة.","prompt":"ما تثنية «عصا» في الرفع؟","correct":"عصوان","w1":"عصيان","w2":"عصاتان","w3":"عصيانان","practice":"ثن أربعة أسماء مقصورة ذات أصول مختلفة، واذكر كيف ظهر الأصل الواوي أو اليائي."},{"n":11,"skill":"إبدال الياء واوًا وفق البنية","passage":"توجد أبواب صرفية تتحول فيها الياء إلى واو بسبب الضمة أو موقع الحرف في البنية، ولا ينبغي توليد مثال عشوائي لم تذكره القاعدة. يطلب هذا التدريب مقارنة الكلمة قبل الإبدال وبعده بالرجوع إلى مصدر صرف موثوق، مع كتابة الوزن والأصل.","prompt":"ما المعلومة الأساسية للحكم بوقوع الإبدال؟","correct":"الأصل الصرفي والصيغة بعد التغيير","w1":"عدد كلمات الجملة","w2":"موضع الاسم في الصفحة","w3":"حركة الفاعل فقط","practice":"وثق مثالين لإبدال الياء واوًا من كتاب صرفي، واشرح موقع الإبدال وعلته في جدول."},{"n":12,"skill":"إبدال الواو والياء ألفًا","passage":"من الإعلال بالقلب تحوّل الواو أو الياء إلى ألف في ظروف صرفية معينة، كما في تحليل «قال» ذي الجذر «قول» و«باع» ذي الجذر «بيع». يتطلب تفسير القاعدة تحديد موقع حرف العلة والحركات الأصلية.","prompt":"ما الجذر الثلاثي للفعل «باع»؟","correct":"بيع","w1":"بوع","w2":"باع","w3":"بيعان","practice":"فسّر الإعلال في خمسة أفعال أجوفة مختلفة، مع تحديد الجذر والصيغة المسموعة قبل الاشتقاق."},{"n":13,"skill":"النداء وأنواع المنادى","passage":"«يا طالبَ العلمِ، اجتهدْ» يتضمن منادى مضافًا منصوبًا، أما «يا محمدُ» فاسم علم مفرد مبني على الضم في محل نصب النداء. تختلف أحكام المنادى بحسب الإضافة والتعريف والنداء المقصود.","prompt":"ما نوع «طالبَ العلم» في النداء؟","correct":"منادى مضاف منصوب","w1":"منادى علم مفرد مبني","w2":"مفعول مطلق","w3":"بدل","practice":"اكتب ست جمل نداء تتنوع فيها أقسام المنادى، واضبط العلامات وعلل."},{"n":14,"skill":"الاختصاص وتوضيح المقصود","passage":"«نحنُ المعلمينَ نحرصُ على التعلم» في سياق النحو المدرسي يمكن تحليل «المعلمينَ» اسمًا منصوبًا على الاختصاص بفعل محذوف وجوبًا تقديره «أخصّ»، ويبين المقصود بالضمير. يختلف الأسلوب عن النداء المباشر.","prompt":"ما وظيفة «المعلمينَ» في أسلوب الاختصاص؟","correct":"اسم منصوب على الاختصاص","w1":"منادى مرفوع","w2":"خبر كان","w3":"مبتدأ","practice":"صغ أربع جمل اختصاص بعد ضمير تكلم أو خطاب ثم قارنها بأمثلة النداء."},{"n":15,"skill":"التحذير والإغراء","passage":"«الصدقَ الصدقَ!» قد يفيد الإغراء بلزوم الصدق في تركيب مناسب، و«إياكَ والكذبَ!» أسلوب تحذير. تُحلل الأسماء المنصوبة وفق الفعل المحذوف وتحدد غاية الكلام من السياق.","prompt":"ما الأسلوب في «إياك والكذب»؟","correct":"تحذير","w1":"تمني","w2":"تعجب","w3":"خبر مثبت","practice":"اكتب خمسة أمثلة للإغراء والتحذير في مواقف يومية، ثم اذكر المحذوف والإعراب المتوقع."},{"n":16,"skill":"الاستفهام الحقيقي والبلاغي","passage":"«متى يبدأ الدرس؟» استفهام حقيقي عن الزمن، وقد يستخدم المتكلم «أليس العلم نورًا؟» لتقرير معنى معروف في السياق البلاغي. تتحدد دلالة الاستفهام من المقام وطريقة الخطاب، وليس من أداة الاستفهام وحدها.","prompt":"أي أداة تستفهم عن الزمن في المثال؟","correct":"متى","w1":"أين","w2":"كم","w3":"من","practice":"اكتب ستة أسئلة تتضمن أدوات متنوعة، وحدد استفهامين خرجا إلى غرض بلاغي وعلل."}]'::jsonb) AS x(
    n integer,skill text,passage text,prompt text,correct text,w1 text,w2 text,w3 text,practice text
  ) LOOP
    SELECT l.id,l.content INTO STRICT target_id,target_content
    FROM public.lessons l
    JOIN public.units u ON u.id=l.unit_id
    JOIN public.grades g ON g.id=u.grade_id AND g.grade_number=12
    JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027' AND cu.id='4611ec73-1e1a-4571-9c51-05d7c901c83f'
    JOIN public.countries c ON c.id=cu.country_id AND c.code='BH'
    WHERE u.title='نحو 311 — النحو والصرف والبلاغة' AND u.semester=1 AND l.sort_order=r.n AND l.status='published'
    FOR UPDATE OF l;
    IF char_length(coalesce(target_content,''))<350 THEN
      UPDATE public.lessons SET
        content='ضاديوم — إثراء مستقل أصلي للصف الثاني عشر، الفصل الأول. لا يمثل النص الوزاري الأصلي ولا يثبت مطابقة العنوان للمصدر.'||E'\n\n'||
          'المهارة: '||r.skill||E'\n\n'||
          'النموذج التعليمي والشرح: '||r.passage||E'\n\n'||
          'أهداف التعلم: يحدد المتعلم شاهدًا صحيحًا ويشرح دلالته، ويميّز بين الفكرة والدليل، ثم ينتج كتابة مناسبة للمهارة.'||E'\n\n'||
          'سؤال الفهم: '||r.prompt||E'\n\n'||
          'التطبيق الكتابي: '||r.practice||E'\n\n'||
          'التمايز: المبتدئ يحصل على كلمات مفتاحية وبداية جملة؛ المتوسط يجيب بدليل مستقل؛ المتقدم يقارن بين صياغتين ويبرر تحسيناته.'||E'\n\n'||
          'مراجعة المعلم: تحقق من صحة الاستدلال والإملاء وعلامات الترقيم والترابط. لا تُمنح درجة جودة تلقائية لمجرد تسليم المهمة.'||E'\n\n'||
          'تنبيه المصدر: راجع العنوان المستورد والكتاب الرسمي قبل وصف هذا التدريب بأنه مطابق للمنهج.'||E'\n\n'||'المدخل السابق المحفوظ: '||coalesce(target_content,''),
        updated_at=now()
      WHERE id=target_id;
    END IF;
    IF EXISTS (SELECT 1 FROM public.lessons WHERE id=target_id AND content LIKE 'ضاديوم — إثراء مستقل أصلي للصف الثاني عشر%') THEN
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'فهم النص الإثرائي','multiple_choice','assessment',r.prompt,
        jsonb_build_object('origin','DADYOOM_BH_RELIGIOUS_G12_T1_NAHW311_ORIGINAL_20261008','notOfficialBook',true,'ocrReview','pending','options',CASE (r.n % 4) WHEN 0 THEN jsonb_build_array(r.correct,r.w1,r.w2,r.w3) WHEN 1 THEN jsonb_build_array(r.w1,r.correct,r.w2,r.w3) WHEN 2 THEN jsonb_build_array(r.w1,r.w2,r.correct,r.w3) ELSE jsonb_build_array(r.w1,r.w2,r.w3,r.correct) END),
        jsonb_build_object('correct',r.correct),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='multiple_choice' AND content->>'origin'='DADYOOM_BH_RELIGIOUS_G12_T1_NAHW311_ORIGINAL_20261008');
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'كتابة تطبيقية بمراجعة المعلم','writing','practice',r.practice,
        jsonb_build_object('origin','DADYOOM_BH_RELIGIOUS_G12_T1_NAHW311_ORIGINAL_20261008','notOfficialBook',true,'humanReviewRequired',true,'text',r.practice,'skillQualityAutoVerified',false),
        jsonb_build_object('grading_mode','completion_only_reference','model_answer','لا تكفي المطابقة النصية؛ يصحح المعلم ملاءمة الأفكار والدليل والترابط.'),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='writing' AND content->>'origin'='DADYOOM_BH_RELIGIOUS_G12_T1_NAHW311_ORIGINAL_20261008');
    END IF;
  END LOOP;
END
$dadyoom$;